INSERT INTO repo_modules (module_id, name, module_no, description, module_sd_id, status) VALUES ('MOD_COURSE_001_M01', 'Foundations & Linear Data Structures', '1', 'Foundations & Linear Data Structures examines Classes and Stacks within Data Structures & Algorithms. Key technical concerns include Abstraction, encapsulation, state and behaviour, modularity, information hiding, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_FOUNDATIONS_LINEAR_DATA_STRUCTURES', 'Active'), ('MOD_COURSE_001_M02', 'Linear Data Structures', '2', 'Linear Data Structures examines Queues and Linked Lists within Data Structures & Algorithms. Key technical concerns include FIFO ordering, abstraction, controlled access, operation complexity, Dynamic linkage, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_LINEAR_DATA_STRUCTURES', 'Active'), ('MOD_COURSE_001_M03', 'Trees & Graphs', '3', 'Trees & Graphs examines Binary Search Tree (BST) and AVL Trees within Data Structures & Algorithms. Key technical concerns include Ordering invariant, recursive structure, search efficiency, height dependence, Height balance, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_TREES_GRAPHS', 'Active'), ('MOD_COURSE_001_M04', 'Sorting & Searching', '4', 'Sorting & Searching examines Quick/Merge sort and Binary Search within Data Structures & Algorithms. Key technical concerns include Divide and conquer, ordering, complexity, partitioning/merging, logarithmic search, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SORTING_SEARCHING', 'Active'), ('MOD_COURSE_001_M05', 'Hashing', '5', 'Hashing examines Collision resolution within Data Structures & Algorithms. Key technical concerns include Hashing, occupancy/load factor, collision management, expected constant-time access under suitable assumptions, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_HASHING', 'Active'), ('MOD_COURSE_002_M01', 'Propositional Logic', '1', 'Propositional Logic examines Truth tables within Discrete Mathematics. Key technical concerns include Boolean semantics, compositional evaluation, logical equivalence, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_PROPOSITIONAL_LOGIC', 'Active'), ('MOD_COURSE_002_M02', 'Proof Techniques', '2', 'Proof Techniques examines Induction within Discrete Mathematics. Key technical concerns include Logical implication, well-founded progression, proof by cases over natural-number structure, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_PROOF_TECHNIQUES', 'Active'), ('MOD_COURSE_002_M03', 'Set Theory & Relations', '3', 'Set Theory & Relations examines Equivalence relations within Discrete Mathematics. Key technical concerns include Reflexivity, symmetry, transitivity, partitioning, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SET_THEORY_RELATIONS', 'Active'), ('MOD_COURSE_002_M04', 'Combinatorics', '4', 'Combinatorics examines Pigeonhole principle within Discrete Mathematics. Key technical concerns include Counting, cardinality, unavoidable repetition, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_COMBINATORICS', 'Active'), ('MOD_COURSE_002_M05', 'Graph Theory', '5', 'Graph Theory examines Trees within Discrete Mathematics. Key technical concerns include Hierarchy, connectivity, acyclicity, recursive decomposition, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_GRAPH_THEORY', 'Active'), ('MOD_COURSE_003_M01', 'ER Modeling', '1', 'ER Modeling examines Entities, relationships & constraints within Database Management Systems. Key technical concerns include Data modelling, integrity, identity, structural constraints, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_ER_MODELING', 'Active'), ('MOD_COURSE_003_M02', 'Relational Model', '2', 'Relational Model examines Relational algebra within Database Management Systems. Key technical concerns include Closure, relational composition, set semantics, query transformation, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_RELATIONAL_MODEL', 'Active'), ('MOD_COURSE_003_M03', 'SQL', '3', 'SQL examines SQL queries within Database Management Systems. Key technical concerns include Declarative querying, set-oriented processing, integrity, transaction semantics, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SQL', 'Active'), ('MOD_COURSE_003_M04', 'Normalization', '4', 'Normalization examines Boyce-Codd Normal Form within Database Management Systems. Key technical concerns include Functional dependency, key-based determination, redundancy reduction, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_NORMALIZATION', 'Active'), ('MOD_COURSE_003_M05', 'Transaction Management', '5', 'Transaction Management examines Concurrency control within Database Management Systems. Key technical concerns include Isolation, serializability, consistency, conflict management, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_TRANSACTION_MANAGEMENT', 'Active'), ('MOD_COURSE_004_M01', 'Processes', '1', 'Processes examines Deadlocks within Operating Systems. Key technical concerns include Mutual exclusion, hold-and-wait, circular wait, resource allocation, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_PROCESSES', 'Active'), ('MOD_COURSE_004_M02', 'Threads & Synchronization', '2', 'Threads & Synchronization examines Thread synchronization within Operating Systems. Key technical concerns include Mutual exclusion, ordering, atomicity, visibility, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_THREADS_SYNCHRONIZATION', 'Active'), ('MOD_COURSE_004_M03', 'CPU Scheduling', '3', 'CPU Scheduling examines Scheduling algorithms within Operating Systems. Key technical concerns include Fairness, responsiveness, throughput, processor utilization, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_CPU_SCHEDULING', 'Active'), ('MOD_COURSE_004_M04', 'Memory Management', '4', 'Memory Management examines Paging and virtual memory within Operating Systems. Key technical concerns include Address-space abstraction, locality, protection, memory utilization, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_MEMORY_MANAGEMENT', 'Active'), ('MOD_COURSE_004_M05', 'File Systems', '5', 'File Systems examines File allocation and organization within Operating Systems. Key technical concerns include Storage organization, locality, allocation efficiency, reliability, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_FILE_SYSTEMS', 'Active'), ('MOD_COURSE_005_M01', 'Digital Logic', '1', 'Digital Logic examines Arithmetic Logic Unit (ALU) within Computer Architecture. Key technical concerns include Combinational logic, arithmetic, Boolean operations, datapath design, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_DIGITAL_LOGIC', 'Active'), ('MOD_COURSE_005_M02', 'Instruction Set Architecture', '2', 'Instruction Set Architecture examines Reduced Instruction Set Computer / Complex Instruction Set Computer (RISC/CISC) within Computer Architecture. Key technical concerns include Instruction-set abstraction, implementation trade-offs, performance, code density, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_INSTRUCTION_SET_ARCHITECTURE', 'Active'), ('MOD_COURSE_005_M03', 'Pipelining', '3', 'Pipelining examines Pipeline hazards within Computer Architecture. Key technical concerns include Pipeline parallelism, dependency management, throughput, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_PIPELINING', 'Active'), ('MOD_COURSE_005_M04', 'Memory Hierarchy', '4', 'Memory Hierarchy examines Caches and virtual memory within Computer Architecture. Key technical concerns include Locality, hierarchy, address translation, latency reduction, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_MEMORY_HIERARCHY', 'Active'), ('MOD_COURSE_005_M05', 'I/O Systems', '5', 'I/O Systems examines I/O organization and interfaces within Computer Architecture. Key technical concerns include Data transfer, synchronization, buffering, device abstraction, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_I_O_SYSTEMS', 'Active'), ('MOD_COURSE_006_M01', 'Divide & Conquer', '1', 'Divide & Conquer examines Merge sort within Design and Analysis of Algorithms. Key technical concerns include Divide and conquer, ordering, stability, predictable complexity, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_DIVIDE_CONQUER', 'Active'), ('MOD_COURSE_006_M02', 'Dynamic Programming', '2', 'Dynamic Programming examines Knapsack within Design and Analysis of Algorithms. Key technical concerns include Combinatorial optimization, optimal substructure, resource allocation, capacity constraints, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_DYNAMIC_PROGRAMMING', 'Active'), ('MOD_COURSE_006_M03', 'Greedy Algorithms', '3', 'Greedy Algorithms examines Activity selection within Design and Analysis of Algorithms. Key technical concerns include Greedy choice, feasibility, optimal substructure, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_GREEDY_ALGORITHMS', 'Active'), ('MOD_COURSE_006_M04', 'Graph Algorithms', '4', 'Graph Algorithms examines Network flow within Design and Analysis of Algorithms. Key technical concerns include Conservation, capacity constraints, residual improvement, optimality, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_GRAPH_ALGORITHMS', 'Active'), ('MOD_COURSE_006_M05', 'NP-Completeness', '5', 'NP-Completeness examines NP-complete problems within Design and Analysis of Algorithms. Key technical concerns include Computational complexity, reduction, tractability boundaries, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_NP_COMPLETENESS', 'Active'), ('MOD_COURSE_007_M01', 'Software Development Life Cycle', '1', 'Software Development Life Cycle examines Process models within Software Engineering. Key technical concerns include Lifecycle management, iteration, risk, stakeholder feedback, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SOFTWARE_DEVELOPMENT_LIFE_CYCLE', 'Active'), ('MOD_COURSE_007_M02', 'Agile & Scrum', '2', 'Agile & Scrum examines Continuous integration and delivery within Software Engineering. Key technical concerns include Automation, repeatability, feedback, quality assurance, traceability, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_AGILE_SCRUM', 'Active'), ('MOD_COURSE_007_M03', 'Requirements Engineering', '3', 'Requirements Engineering examines Use cases and requirements specification within Software Engineering. Key technical concerns include Stakeholder needs, completeness, consistency, verifiability, traceability, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_REQUIREMENTS_ENGINEERING', 'Active'), ('MOD_COURSE_007_M04', 'System Design', '4', 'System Design examines Design patterns within Software Engineering. Key technical concerns include Abstraction, coupling/cohesion, reuse, trade-offs, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SYSTEM_DESIGN', 'Active'), ('MOD_COURSE_007_M05', 'Software Testing', '5', 'Software Testing examines Unit and integration testing within Software Engineering. Key technical concerns include Verification, isolation, interface correctness, regression detection, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SOFTWARE_TESTING', 'Active'), ('MOD_COURSE_008_M01', 'Physical Layer', '1', 'Physical Layer examines Transmission media and signalling within Computer Networks. Key technical concerns include Signal integrity, bandwidth, attenuation, interference, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_PHYSICAL_LAYER', 'Active'), ('MOD_COURSE_008_M02', 'Data Link Layer', '2', 'Data Link Layer examines Framing and MAC within Computer Networks. Key technical concerns include Framing, addressing, error detection, medium access, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_DATA_LINK_LAYER', 'Active'), ('MOD_COURSE_008_M03', 'Network Layer', '3', 'Network Layer examines IP addressing and routing within Computer Networks. Key technical concerns include Hierarchical addressing, forwarding, reachability, path selection, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_NETWORK_LAYER', 'Active'), ('MOD_COURSE_008_M04', 'Transport Layer', '4', 'Transport Layer examines Transmission Control Protocol / User Datagram Protocol (TCP/UDP) within Computer Networks. Key technical concerns include End-to-end transport, multiplexing, reliability, congestion management, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_TRANSPORT_LAYER', 'Active'), ('MOD_COURSE_008_M05', 'Application Layer', '5', 'Application Layer examines Hypertext Transfer Protocol (HTTP) within Computer Networks. Key technical concerns include Request/response, resource identification, stateless application semantics, extensibility, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_APPLICATION_LAYER', 'Active'), ('MOD_COURSE_009_M01', 'Simple Stresses', '1', 'Simple Stresses examines Hooke''s Law within Mechanics of Materials. Key technical concerns include Elasticity, proportionality, material stiffness, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SIMPLE_STRESSES', 'Active'), ('MOD_COURSE_009_M02', 'Bending Moment', '2', 'Bending Moment examines Flexure formula within Mechanics of Materials. Key technical concerns include Equilibrium, compatibility, elastic bending, section geometry, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_BENDING_MOMENT', 'Active'), ('MOD_COURSE_009_M03', 'Bending Stresses', '3', 'Bending Stresses examines Bending stress distribution within Mechanics of Materials. Key technical concerns include Stress distribution, neutral axis, section geometry, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_BENDING_STRESSES', 'Active'), ('MOD_COURSE_009_M04', 'Torsion', '4', 'Torsion examines Circular shafts within Mechanics of Materials. Key technical concerns include Torsion, shear stress, stiffness, strength, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_TORSION', 'Active'), ('MOD_COURSE_009_M05', 'Deflection', '5', 'Deflection examines Beam deflection methods within Mechanics of Materials. Key technical concerns include Compatibility, stiffness, deformation, boundary conditions, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_DEFLECTION', 'Active'), ('MOD_COURSE_010_M01', 'Fluid Properties', '1', 'Fluid Properties examines Viscosity within Fluid Mechanics. Key technical concerns include Defining mechanism/properties, governing conditions, assumptions and limitations, application/performance criteria for Viscosity, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_FLUID_PROPERTIES', 'Active'), ('MOD_COURSE_010_M02', 'Hydrostatics', '2', 'Hydrostatics examines Buoyancy within Fluid Mechanics. Key technical concerns include Hydrostatic pressure, displaced volume, force equilibrium, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_HYDROSTATICS', 'Active'), ('MOD_COURSE_010_M03', 'Kinematics', '3', 'Kinematics examines Continuity within Fluid Mechanics. Key technical concerns include Mass conservation, flux balance, continuity, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_KINEMATICS', 'Active'), ('MOD_COURSE_010_M04', 'Dynamics', '4', 'Dynamics examines Reynolds number within Fluid Mechanics. Key technical concerns include Dimensional analysis, inertial-viscous balance, dynamic similarity, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_DYNAMICS', 'Active'), ('MOD_COURSE_010_M05', 'Pipe Flow', '5', 'Pipe Flow examines Head loss and pipe-flow analysis within Fluid Mechanics. Key technical concerns include Energy conservation, friction, hydraulic resistance, efficiency, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_PIPE_FLOW', 'Active') ON CONFLICT DO NOTHING;